test('overdueInvoices sorts by daysOverdue descending (most overdue first)', () => {
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      status: 'issued',
      dueDate: '2026-10-05',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      status: 'issued',
      dueDate: '2026-10-01',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-003',
      status: 'issued',
      dueDate: '2026-10-03',
      lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
    },
  ];
  const result = overdueInvoices(invoices, '2026-10-07');
